-- Дилеры получают числовой ключ id; объявления и контакты ссылаются на него (dealer_id).
-- Шаг 1 из 2: новые колонки и заполнение из slug. Старые колонки удаляет 0002_drop_dealer_copies.
-- Написано вручную поверх drizzle-kit generate: он не знает имени старого первичного ключа и не переносит данные

-- slug перестаёт быть первичным ключом, но остаётся уникальным; старые ссылки по slug пересоздаём на уникальный индекс
ALTER TABLE "listings" DROP CONSTRAINT "listings_dealer_slug_dealers_slug_fk";--> statement-breakpoint
ALTER TABLE "dealer_contacts" DROP CONSTRAINT "dealer_contacts_dealer_slug_dealers_slug_fk";--> statement-breakpoint
ALTER TABLE "dealers" DROP CONSTRAINT "dealers_pkey";--> statement-breakpoint
ALTER TABLE "dealers" ADD CONSTRAINT "dealers_slug_unique" UNIQUE("slug");--> statement-breakpoint
ALTER TABLE "listings" ADD CONSTRAINT "listings_dealer_slug_dealers_slug_fk" FOREIGN KEY ("dealer_slug") REFERENCES "public"."dealers"("slug") ON DELETE cascade ON UPDATE cascade;--> statement-breakpoint
ALTER TABLE "dealer_contacts" ADD CONSTRAINT "dealer_contacts_dealer_slug_dealers_slug_fk" FOREIGN KEY ("dealer_slug") REFERENCES "public"."dealers"("slug") ON DELETE cascade ON UPDATE cascade;--> statement-breakpoint

-- новый ключ: существующие дилеры получают номера 1, 2, 3… автоматически
ALTER TABLE "dealers" ADD COLUMN "id" integer PRIMARY KEY NOT NULL GENERATED BY DEFAULT AS IDENTITY (sequence name "dealers_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1);--> statement-breakpoint

-- ссылки на дилера по номеру, заполняем по slug
ALTER TABLE "dealer_contacts" ADD COLUMN "dealer_id" integer;--> statement-breakpoint
ALTER TABLE "listings" ADD COLUMN "dealer_id" integer;--> statement-breakpoint
UPDATE "dealer_contacts" c SET "dealer_id" = d."id" FROM "dealers" d WHERE d."slug" = c."dealer_slug";--> statement-breakpoint
UPDATE "listings" l SET "dealer_id" = d."id" FROM "dealers" d WHERE d."slug" = l."dealer_slug";--> statement-breakpoint
ALTER TABLE "dealer_contacts" ADD CONSTRAINT "dealer_contacts_dealer_id_dealers_id_fk" FOREIGN KEY ("dealer_id") REFERENCES "public"."dealers"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "listings" ADD CONSTRAINT "listings_dealer_id_dealers_id_fk" FOREIGN KEY ("dealer_id") REFERENCES "public"."dealers"("id") ON DELETE cascade ON UPDATE no action;
